from enum import IntEnum
from roman import to_roman, is_roman_numeral

places = ((1000, ('', 'M', 'MM', 'MMM')), (100, ('', 'C', 'CC', 'CCC', 'CD', 'D', 'DC', 'DCC', 'DCCC', 'CM')), (10, ('', 'X', 'XX', 'XXX', 'XL', 'L', 'LX', 'LXX', 'LXXX', 'XC')), (1, ('', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX')))
for n in range(1, 4000):
    expected = ''.join(symbols[n // place % 10] for place, symbols in places)
    assert to_roman(n) == expected, n

